def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)
    with io.open(os.path.join(root, SEEDER_PATH), encoding="utf-8") as f:
        seeder = f.read()

    if "email_integrations" in data:
        print("Already applied. Nothing to do.")
        return
    if '"3.141.0"' not in init:
        sys.exit("ABORT: not at v3.141.0.")

    old_order = 'ORDER = ["sysadmin_function", "users_permissions", "master_governance", "backups_continuity", "changes_updates"]'
    new_order = 'ORDER = ["sysadmin_function", "users_permissions", "master_governance", "backups_continuity", "changes_updates", "email_integrations"]'
    if seeder.count(old_order) != 1:
        sys.exit(f"ABORT: seeder ORDER anchor not found exactly once ({seeder.count(old_order)}).")

    problems = []
    if len(LESSONS) != 9:
        problems.append(f"  {len(LESSONS)} lessons (want 9)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if len(QUESTIONS) != 35:
        problems.append(f"  {len(QUESTIONS)} questions (want 35)")
    for q in QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    print(f"Sysadmin 6: 9 chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["email_integrations"] = {
        "title": "Sysadmin 6 — Printing, Email & Integrations",
        "desc": "Every message and integration has an owner: the email machinery with firm-domain identity and custodied credentials, the queue as the outbound ledger, the communication map with recipient hygiene, the integration inventory with the build boundary, API key custody with rotation by events, and designed failure modes with monthly reconciliation where money and statute flow.",
        "lessons": LESSONS,
        "questions": bank,
    }
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, SEEDER_PATH), "w", encoding="utf-8") as f:
        f.write(seeder.replace(old_order, new_order, 1))
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.141.0"', '"3.142.0"'))
    print("  data: Sysadmin 6 appended; seeder ORDER extended")
    print("wrote __version__ -> 3.142.0")


if __name__ == "__main__":
    main()
